function bind() {
  document.querySelector('.menu-toggle')?.addEventListener('click', () => document.querySelector('.site-header nav')?.classList.toggle('is-open'));
  document.querySelectorAll('.simple-contact').forEach((form) => {
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      const statusMsg = form.querySelector('.form-message');
      if (statusMsg) {
        if (form.classList.contains('conversation-form')) {
          statusMsg.textContent = 'Thank you for your brief. An Apex advisory coordinator will contact you within one business day to schedule your consultation.';
        } else if (form.classList.contains('visa-assistance-form')) {
          statusMsg.textContent = 'Your visa assistance inquiry has been received. Our mobility team will review your eligibility criteria and reach out promptly.';
        } else if (form.classList.contains('automation-form')) {
          statusMsg.textContent = 'Thank you for requesting an AI blueprint. Our automation architects are preparing your custom assessment.';
        } else if (form.classList.contains('advisory-session-form')) {
          statusMsg.textContent = 'Your advisory session request has been submitted. We will confirm your preferred format and calendar slot shortly.';
        } else {
          statusMsg.textContent = 'Thank you for reaching out. An Apex advisory specialist will review your enquiry and respond within one business day.';
        }
        statusMsg.style.color = '#206e7c';
        statusMsg.style.fontWeight = '700';
      }
      form.reset();
    });
  });

  document.querySelector('.insight-subscribe')?.addEventListener('submit', (event) => {
    event.preventDefault();
    const signupMsg = event.currentTarget.querySelector('.signup-status');
    if (signupMsg) {
      signupMsg.textContent = 'Thank you for subscribing to Apex Executive Briefings.';
      signupMsg.style.color = '#206e7c';
      signupMsg.style.fontWeight = '700';
    }
    event.currentTarget.reset();
  });

  const insightCards = [...document.querySelectorAll('.insights-listing-card')];
  const filterInsights = (category = 'all', tag = '') => {
    const matches = insightCards.filter((card) => (category === 'all' || card.dataset.category === category) && (!tag || card.dataset.tags.split('|').includes(tag)));
    insightCards.forEach((card) => { card.hidden = !matches.includes(card) || matches.indexOf(card) >= 6; });
    const loadMore = document.querySelector('.insights-load-more');
    if (loadMore) loadMore.hidden = matches.length <= 6;
  };
  document.querySelectorAll('[data-insights-filter]').forEach((button) => button.addEventListener('click', () => {
    document.querySelectorAll('[data-insights-filter]').forEach((item) => item.classList.toggle('is-active', item === button));
    document.querySelectorAll('[data-insights-tag]').forEach((item) => item.classList.remove('is-active'));
    filterInsights(button.dataset.insightsFilter);
  }));
  document.querySelectorAll('[data-insights-tag]').forEach((button) => button.addEventListener('click', () => {
    const active = button.classList.toggle('is-active');
    document.querySelectorAll('[data-insights-tag]').forEach((item) => { if (item !== button) item.classList.remove('is-active'); });
    document.querySelectorAll('[data-insights-filter]').forEach((item) => item.classList.toggle('is-active', item.dataset.insightsFilter === 'all'));
    filterInsights('all', active ? button.dataset.insightsTag : '');
  }));
  document.querySelector('.insights-load-more')?.addEventListener('click', (event) => {
    insightCards.filter((card) => card.hidden).slice(0, 6).forEach((card) => { card.hidden = false; });
    if (!insightCards.some((card) => card.hidden)) event.currentTarget.hidden = true;
  });

  document.querySelectorAll('[data-share]').forEach((button) => button.addEventListener('click', () => {
    const url = encodeURIComponent(location.href);
    const title = encodeURIComponent(document.querySelector('.article-detail h1')?.textContent || document.title);
    const destinations = { facebook: `https://www.facebook.com/sharer/sharer.php?u=${url}`, twitter: `https://twitter.com/intent/tweet?text=${title}&url=${url}`, linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${url}` };
    window.open(destinations[button.dataset.share], '_blank', 'noopener,noreferrer,width=640,height=520');
  }));
}

function render() {
  const info = routeInfo();
  const pages = {
    about: aboutPage,
    services: servicesPageRedesign,
    insights: freshInsightsPage,
    contact: contactPage,
    conversation: conversationPage,
    'visa-assistance': visaAssistancePage,
    automation: automationPage,
    'advisory-session': advisorySessionPage,
    advisors: advisorsPage,
    article: () => singleArticlePage(info.slug)
  };
  const page = pages[info.view] ? pages[info.view]() : info.view === 'privacy-policy' ? legal('Privacy Policy') : info.view === 'terms-and-conditions' ? legal('Terms & Conditions') : freshInsightsPage();
  const mainClass = ['about', 'services', 'insights', 'contact', 'article', 'conversation', 'visa-assistance', 'automation', 'advisory-session', 'advisors'].includes(info.view) ? `${info.view}-main` : '';
  app.innerHTML = `${header()}<main class="consult-main ${mainClass}">${page}</main>${footer()}`;
  bind();
}

function bindLegacyHome() {
  const menuButton = document.querySelector('.site-header .menu-button');
  const navigation = document.querySelector('.site-header .desktop-nav');
  menuButton?.addEventListener('click', () => {
    const isOpen = menuButton.getAttribute('aria-expanded') === 'true';
    menuButton.setAttribute('aria-expanded', String(!isOpen));
    navigation?.classList.toggle('is-open', !isOpen);
  });

  const revealTargets = document.querySelectorAll('.reveal');
  if (revealTargets.length && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-in');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: .2 });
    revealTargets.forEach((target) => {
      target.classList.add('reveal-armed');
      observer.observe(target);
    });
  }
}

function applySharedContentToPage() {
  const footerText = document.querySelector('.footer-bottom span');
  const footerCopyright = document.querySelector('.footer-bottom span:last-child');
  if (footerText) footerText.textContent = content.settings.footer;
  if (footerCopyright) footerCopyright.innerHTML = `&copy; 2026 ${content.settings.name}. All rights reserved.`;

  const heroEyebrow = document.querySelector('.hero .eyebrow');
  if (heroEyebrow && content.settings.tagline) {
    heroEyebrow.textContent = content.settings.tagline.toUpperCase();
  }

  const icons = content.settings.icons || {};
  document.querySelectorAll('.icon-entry').forEach((icon) => { icon.title = icons.entry || 'MISA'; });
  document.querySelectorAll('.icon-advisory').forEach((icon) => { icon.title = icons.advisory || 'ADVISORY'; });
  document.querySelectorAll('.icon-learning').forEach((icon) => { icon.title = icons.learning || 'LEARNING'; });
  document.querySelectorAll('.icon-support').forEach((icon) => { icon.title = icons.support || 'PRO/GRO'; });

  if (route() === 'insights') {
    const featured = content.articles[0];
    const featuredImage = document.querySelector('.fresh-feature-image');
    const featuredTitle = document.querySelector('.fresh-feature h2');
    const featuredCategory = document.querySelector('.fresh-feature-meta span');
    if (featured) {
      if (featuredImage) { featuredImage.src = featured.image; featuredImage.alt = featured.title; }
      if (featuredTitle) featuredTitle.textContent = featured.title;
      if (featuredCategory) featuredCategory.textContent = featured.category;
    }
    document.querySelectorAll('.fresh-more-card').forEach((card, index) => {
      const article = content.articles[index + 1];
      if (!article) return;
      const title = card.querySelector('h3');
      if (title) title.textContent = article.title;
    });
  }
}

function renderSite() {
  if (location.hash.startsWith('#/dashboard') || location.pathname.replace(/\/+$/, '') === '/dashboard') {
    location.replace('dashboard.html');
    return;
  }
  const isHome = route() === 'home';
  consultingStyles.disabled = isHome;
  if (isHome) {
    app.innerHTML = legacyHome;
    bindLegacyHome();
  } else {
    render();
  }
  applySharedContentToPage();
  updatePageMetadata();
  normalizeImages();
}

function syncFromStorage() {
  const saved = localStorage.getItem(storeKey);
  if (!saved || saved === lastSyncedValue) return;
  try {
    const next = JSON.parse(saved);
    lastSyncedValue = saved;
    content.settings = { ...content.settings, ...next.settings };
    content.articles = next.articles || content.articles;
    content.countries = next.countries || content.countries;
    content.logs = next.logs || content.logs;
    renderSite();
  } catch {
  }
}

window.addEventListener('storage', (event) => {
  if (event.key === storeKey) syncFromStorage();
});

window.setInterval(syncFromStorage, 1000);

document.addEventListener('click', (event) => {
  if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const anchor = event.target.closest('a');
  if (!anchor || anchor.target === '_blank' || anchor.hasAttribute('download')) return;
  const href = anchor.getAttribute('href') || '';
  if (!href || href.startsWith('#') || href.startsWith('http:') || href.startsWith('https:') || href.startsWith('mailto:') || href.startsWith('tel:') || /\.[a-z0-9]+$/i.test(href.split(/[?#]/)[0])) return;
  event.preventDefault();
  navigate(href);
});

window.addEventListener('popstate', renderSite);
window.addEventListener('hashchange', renderSite);
renderSite();
